+// API keys, roles and the audit trail. Keys live in the store as
+// `apiKeys: [{ key, name, role }]`; every request that changes data leaves an
+// entry in `audit` (docs/DATA.md).
+import { timingSafeEqual } from "node:crypto";
+
+// What each role may do, by action name. Routes name the action they need:
+// "read" for GET; "cook", "waste", "temperature" and "count" for kitchen
+// work; anything else is "manage". Managers may do everything.
+const ROLES = Object.freeze({
+  viewer: ["read"],
+  cook: ["read", "cook", "waste", "temperature", "count"],
+  manager: null,
+});
+
+/** Whether `role` may perform `action`. */
+export function may(role, action) {
+  if (!Object.hasOwn(ROLES, role)) return false;
+  const allowed = ROLES[role];
+  return allowed === null || allowed.includes(action);
+}
+
+/** The API key record ({ name, role }) matching the presented key, or null. */
+export function findKey(store, presented) {
+  if (typeof presented !== "string" || presented === "") return null;
+  const given = Buffer.from(presented);
+  for (const k of store.data.apiKeys ?? []) {
+    if (typeof k.key !== "string") continue;
+    const known = Buffer.from(k.key);
+    if (known.length === given.length && timingSafeEqual(known, given)) return { name: k.name, role: k.role };
+  }
+  return null;
+}
+
+/** Appends an audit entry { at, keyName, method, path, status }. */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  const entry = { at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse().sort((a, b) => (a.at < b.at ? 1 : a.at > b.at ? -1 : 0));
+}
