@@ -0,0 +1,69 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, auth, fresh } from "./helpers.js";
+
+test("no key or an unknown key is 401", async () => {
+  const { raw } = app();
+  const none = await raw({ path: "/items" });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  const unknown = await raw({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(unknown.status, 401);
+  const notBearer = await raw({ path: "/items", headers: { authorization: "manager-dev-key" } });
+  assert.equal(notBearer.status, 401);
+  assert.equal((await raw({ path: "/nope" })).status, 401);
+});
+
+test("viewers may only read", async () => {
+  const { handle, store } = app(fresh(), { role: "viewer" });
+  assert.equal((await handle({ path: "/items" })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(res.status, 403);
+  assert.equal(res.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+  assert.equal((await handle({ path: "/audit" })).status, 403);
+});
+
+test("cooks may cook, waste, log temperatures and count, nothing else", async () => {
+  const { handle } = app(fresh(), { role: "cook" });
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", body: { qty: 1 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/orders/1/send" })).status, 403);
+  assert.equal((await handle({ method: "PUT", path: "/items/1/allergens", body: { allergens: [] } })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/jobs/nightly" })).status, 403);
+  assert.equal((await handle({ path: "/audit" })).status, 403);
+});
+
+test("cooks enter counts on a stock-take a manager started", async () => {
+  const store = fresh();
+  const take = (await app(store).handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  const { handle } = app(store, { role: "cook" });
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: 6, counted: 12 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 403);
+});
+
+test("changes are audited and managers read the audit newest first", async () => {
+  const store = fresh();
+  const cook = app(store, { role: "cook" }).handle;
+  const { handle, raw } = app(store);
+  await cook({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  await cook({ method: "POST", path: "/orders/1/send" });
+  await handle({ path: "/items" });
+  await raw({ method: "POST", path: "/jobs/nightly" });
+  const res = await handle({ path: "/audit" });
+  assert.equal(res.status, 200);
+  assert.deepEqual(res.body.map((e) => [e.keyName, e.method, e.path, e.status]), [
+    ["line cook", "POST", "/orders/1/send", 403],
+    ["line cook", "POST", "/recipes/1/cook", 200],
+  ]);
+  assert.equal(res.body[0].at, "2026-10-28T10:00:00.000Z");
+  assert.ok(!JSON.stringify(res.body).includes("dev-key"));
+});
+
+test("the header name is case-insensitive", async () => {
+  const { raw } = app();
+  assert.equal((await raw({ path: "/items", headers: { Authorization: auth("viewer").authorization } })).status, 200);
+});
